/* Materia Hub - standalone animated charcoal marble.
 * SINGLE FILE: stone image, styling, colors and motion are all inside this JS.
 * Already connected in designers.html and solutions.html (EL / EN / PT).
 * Future effect changes: replace only /marble-background.js.
 * No edits to HTML or other image files are needed.
 */
(() => {
  'use strict';

  // Change only these values to tune the animation across all 6 pages.
  const SETTINGS = {
    stoneSeconds: 18,
    veinsSeconds: 14,
    lightSeconds: 11,
    backgroundColor: '#1b1d20'
  };

  // Embedded WebP stone texture, so no external image file is required.
  const marbleImage = 'data:image/webp;base64,';


  const css = `
    .architecture-section[data-marble-background] {
      position: relative;
      isolation: isolate;
      background-color: ${SETTINGS.backgroundColor};
      color: #f3f0ea;
      /* overflow:hidden makes position:sticky stop following the viewport.
         overflow:clip clips the layers without creating a scroll container. */
      overflow: clip;
    }
    .architecture-section[data-marble-background] > .mh-marble-bg {
      position: absolute;
      inset: 0;
      z-index: 0;
      overflow: clip;
      pointer-events: none;
      background-color: ${SETTINGS.backgroundColor};
      /* Continuously covers long sections even beyond the animated viewport. */
      background-image: linear-gradient(rgba(5, 6, 8, .38), rgba(5, 6, 8, .38)), var(--mh-marble-image);
      background-size: auto, 1400px auto;
      background-position: center;
      background-repeat: repeat;
    }
    .mh-marble-bg__viewport {
      position: sticky;
      top: 0;
      width: 100%;
      height: 100vh;
      height: 100svh;
      overflow: hidden;
      background: ${SETTINGS.backgroundColor};
    }
    .mh-marble-bg__stone,
    .mh-marble-bg__veins,
    .mh-marble-bg__light,
    .mh-marble-bg__shade {
      position: absolute;
      pointer-events: none;
    }
    .mh-marble-bg__stone {
      inset: -16%;
      background-image: var(--mh-marble-image);
      background-size: cover;
      background-position: center;
      filter: contrast(1.22) saturate(.78);
      animation: mh-marble-flow ${SETTINGS.stoneSeconds}s ease-in-out infinite alternate;
      will-change: transform;
    }
    /* A second, translucent copy of the real stone creates moving veins. */
    .mh-marble-bg__veins {
      inset: -16%;
      background-image: var(--mh-marble-image);
      background-position: center;
      background-size: cover;
      filter: grayscale(1) brightness(1.25) contrast(1.9);
      mix-blend-mode: screen;
      opacity: .23;
      -webkit-mask-image: radial-gradient(ellipse 80% 80% at 48% 50%, black 18%, transparent 88%);
      mask-image: radial-gradient(ellipse 80% 80% at 48% 50%, black 18%, transparent 88%);
      animation: mh-marble-veins ${SETTINGS.veinsSeconds}s ease-in-out infinite alternate;
      will-change: transform, opacity;
    }
    .mh-marble-bg__light {
      inset: -20%;
      background:
        radial-gradient(ellipse 30% 40% at 20% 30%, rgba(208, 210, 216, .21), transparent 92%),
        radial-gradient(ellipse 42% 40% at 79% 62%, rgba(173, 178, 186, .15), transparent 95%),
        linear-gradient(112deg, transparent 27%, rgba(229, 230, 229, .12) 48%, transparent 65%);
      mix-blend-mode: screen;
      animation: mh-marble-light ${SETTINGS.lightSeconds}s ease-in-out infinite alternate;
      will-change: transform, opacity;
    }
    .mh-marble-bg__shade {
      inset: 0;
      background:
        linear-gradient(180deg, rgba(5, 6, 8, .22), transparent 23%, transparent 82%, rgba(4, 5, 6, .22)),
        linear-gradient(90deg, rgba(4, 5, 7, .18), transparent 40%, rgba(4, 5, 7, .17));
    }
    @keyframes mh-marble-flow {
      from { transform: scale(1.10) translate3d(-6%, -3%, 0); }
      to   { transform: scale(1.17) translate3d(6%, 3%, 0); }
    }
    @keyframes mh-marble-veins {
      from { transform: scale(1.14) translate3d(5%, -4%, 0) rotate(-1.5deg); opacity: .17; }
      to   { transform: scale(1.07) translate3d(-5%, 4%, 0) rotate(1.5deg); opacity: .28; }
    }
    @keyframes mh-marble-light {
      from { transform: translate3d(-14%, -4%, 0) rotate(-2deg); opacity: .65; }
      to   { transform: translate3d(14%, 4%, 0) rotate(2deg); opacity: 1; }
    }

    .architecture-section[data-marble-background] .architecture-info h2,
    .architecture-section[data-marble-background] .materials-heading h3,
    .architecture-section[data-marble-background] .architecture-closing p {
      color: #f5f2ec;
    }
    .architecture-section[data-marble-background] .architecture-info > p { color: #d0d0cf; }
    .architecture-section[data-marble-background] .materials-count { color: #c4c0bc; }
    .architecture-section[data-marble-background] .eyebrow.dark,
    .architecture-section[data-marble-background] .architecture-closing span { color: #e18b91; }
    .architecture-section[data-marble-background] .materials-heading,
    .architecture-section[data-marble-background] .architecture-closing {
      border-top-color: rgba(255,255,255,.23);
    }
    .architecture-section[data-marble-background] .architecture-line {
      z-index: 1;
      opacity: .40;
    }
    .architecture-section[data-marble-background] .architecture-line path { stroke: #bd5660; }
    .architecture-section[data-marble-background] .architecture-line circle { fill: #bd5660; }
    .architecture-section[data-marble-background] > .container {
      position: relative;
      z-index: 2;
    }

    @media (max-width: 768px) {
      .mh-marble-bg__stone,
      .mh-marble-bg__veins { inset: -20%; }
      .architecture-section[data-marble-background] .architecture-line { opacity: .30; }
    }
    @media (prefers-reduced-motion: reduce) {
      .mh-marble-bg__stone,
      .mh-marble-bg__veins,
      .mh-marble-bg__light {
        animation: none !important;
        will-change: auto;
      }
    }
  `;

  function init() {
    const sections = document.querySelectorAll('[data-marble-background]');
    if (!sections.length) return;
    if (!document.getElementById('mh-marble-styles')) {
      const style = document.createElement('style');
      style.id = 'mh-marble-styles';
      style.textContent = css;
      document.head.appendChild(style);
    }
    sections.forEach(section => {
      if (section.querySelector('.mh-marble-bg')) return;
      const bg = document.createElement('div');
      bg.className = 'mh-marble-bg';
      bg.setAttribute('aria-hidden', 'true');
      bg.style.setProperty('--mh-marble-image', `url("${marbleImage}")`);
      bg.innerHTML = '<div class="mh-marble-bg__viewport"><div class="mh-marble-bg__stone"></div><div class="mh-marble-bg__veins"></div><div class="mh-marble-bg__light"></div><div class="mh-marble-bg__shade"></div></div>';
      section.insertBefore(bg, section.firstChild);
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init, { once: true });
  } else {
    init();
  }
})();
